import { Method, type MatrixHttpApi, type IHttpOpts } from "../http-api/index.ts";
import type { IKeyValueStore } from "../store/KeyValueStore.ts";
import type { ISyncResponse, IRoomEvent } from "../sync-accumulator.ts";
import { logger } from "../logger.ts";

export interface IncrementalSyncOptions {
    batchSize?: number;
    maxBackoff?: number;
    initialBackoff?: number;
}

export interface RoomSyncState {
    prevBatch: string;
    events: IRoomEvent[];
    state: Map<string, IRoomEvent>;
}

export interface ISyncStateData {
    next_batch: string;
    account_data?: { events: IRoomEvent[] };
    presence?: { events: IRoomEvent[] };
    rooms?: {
        invite?: Record<
            string,
            {
                invite_state: { events: IRoomEvent[] };
            }
        >;
        join?: Record<
            string,
            {
                timeline: { events: IRoomEvent[] };
                state: { events: IRoomEvent[] };
            }
        >;
        leave?: Record<
            string,
            {
                timeline: { events: IRoomEvent[] };
                state: { events: IRoomEvent[] };
            }
        >;
    };
}

export class IncrementalSyncManager {
    private syncToken: string | null = null;
    private roomStates: Map<string, RoomSyncState> = new Map();
    private pendingEvents: Map<string, IRoomEvent[]> = new Map();
    private backoff: number;
    private maxBackoff: number;
    private batchSize: number;

    public constructor(
        private http: MatrixHttpApi<IHttpOpts>,
        private store: IKeyValueStore,
        options: IncrementalSyncOptions = {},
    ) {
        this.batchSize = options.batchSize ?? 100;
        this.maxBackoff = options.maxBackoff ?? 60000;
        this.backoff = options.initialBackoff ?? 1000;

        this.loadState();
    }

    public async syncOnce(since?: string, timeout = 30000): Promise<Partial<ISyncResponse>> {
        const syncToken = since ?? this.syncToken;

        try {
            const response = await this.http.authedRequest<ISyncStateData>(Method.Get, "/sync", {
                since: syncToken ?? undefined,
                timeout,
            });

            this.syncToken = response.next_batch;
            await this.saveState();

            await this.processSyncResponse(response);

            this.backoff = 1000;
            return response as Partial<ISyncResponse>;
        } catch (error) {
            const errorObj = error as Error;
            logger.error("Sync failed:", errorObj);

            this.backoff = Math.min(this.backoff * 2, this.maxBackoff);
            throw errorObj;
        }
    }

    public async syncIncremental(roomId: string, limit?: number): Promise<IRoomEvent[]> {
        const roomState = this.roomStates.get(roomId);
        if (!roomState) {
            return [];
        }

        const pending = this.pendingEvents.get(roomId) ?? [];
        const batchSize = limit ?? this.batchSize;

        const events = pending.slice(0, batchSize);
        this.pendingEvents.set(roomId, pending.slice(batchSize));

        return events;
    }

    public getSyncToken(): string | null {
        return this.syncToken;
    }

    public setSyncToken(token: string): void {
        this.syncToken = token;
        this.saveState();
    }

    public getRoomState(roomId: string): RoomSyncState | undefined {
        return this.roomStates.get(roomId);
    }

    public getPendingEvents(roomId: string): IRoomEvent[] {
        return this.pendingEvents.get(roomId) ?? [];
    }

    public clearRoomState(roomId: string): void {
        this.roomStates.delete(roomId);
        this.pendingEvents.delete(roomId);
    }

    public clearAllStates(): void {
        this.roomStates.clear();
        this.pendingEvents.clear();
    }

    public getBackoff(): number {
        return this.backoff;
    }

    public resetBackoff(): void {
        this.backoff = 1000;
    }

    private async processSyncResponse(response: ISyncStateData): Promise<void> {
        const rooms = response.rooms ?? {};

        const joinRooms = rooms.join ?? {};
        for (const roomId of Object.keys(joinRooms)) {
            await this.processJoinedRoom(roomId, joinRooms[roomId]);
        }

        const inviteRooms = rooms.invite ?? {};
        for (const roomId of Object.keys(inviteRooms)) {
            await this.processInvitedRoom(roomId, inviteRooms[roomId]);
        }

        const leaveRooms = rooms.leave ?? {};
        for (const roomId of Object.keys(leaveRooms)) {
            await this.processLeftRoom(roomId, leaveRooms[roomId]);
        }
    }

    private async processJoinedRoom(roomId: string, roomData: unknown): Promise<void> {
        const data = roomData as {
            state?: { events?: IRoomEvent[] };
            timeline?: { events?: IRoomEvent[]; prev_batch?: string };
            ephemeral?: { events?: IRoomEvent[] };
            account_data?: { events?: IRoomEvent[] };
        };

        let roomState = this.roomStates.get(roomId);

        if (!roomState) {
            roomState = {
                prevBatch: data.timeline?.prev_batch ?? "",
                events: [],
                state: new Map(),
            };
            this.roomStates.set(roomId, roomState);
        }

        if (data.timeline?.prev_batch) {
            roomState.prevBatch = data.timeline.prev_batch;
        }

        if (data.state?.events) {
            for (const event of data.state.events) {
                roomState.state.set(event.event_id, event);
            }
        }

        if (data.timeline?.events) {
            const pending = this.pendingEvents.get(roomId) ?? [];
            pending.push(...data.timeline.events);
            this.pendingEvents.set(roomId, pending);
        }

        await this.saveRoomState(roomId);
    }

    private async processInvitedRoom(roomId: string, roomData: unknown): Promise<void> {
        const data = roomData as { invite_state?: { events?: IRoomEvent[] } };

        if (data.invite_state?.events) {
            const roomState: RoomSyncState = {
                prevBatch: "",
                events: data.invite_state.events,
                state: new Map(),
            };

            for (const event of data.invite_state.events) {
                roomState.state.set(event.event_id, event);
            }

            this.roomStates.set(roomId, roomState);
            await this.saveRoomState(roomId);
        }
    }

    private async processLeftRoom(roomId: string, roomData: unknown): Promise<void> {
        const data = roomData as {
            state?: { events?: IRoomEvent[] };
            timeline?: { events?: IRoomEvent[]; prev_batch?: string };
        };

        let roomState = this.roomStates.get(roomId);

        if (!roomState) {
            roomState = {
                prevBatch: data.timeline?.prev_batch ?? "",
                events: [],
                state: new Map(),
            };
        }

        if (data.state?.events) {
            for (const event of data.state.events) {
                roomState.state.set(event.event_id, event);
            }
        }

        if (data.timeline?.events) {
            const pending = this.pendingEvents.get(roomId) ?? [];
            pending.push(...data.timeline.events);
            this.pendingEvents.set(roomId, pending);
        }

        this.roomStates.set(roomId, roomState);
        await this.saveRoomState(roomId);
    }

    private async saveState(): Promise<void> {
        if (this.syncToken) {
            await this.store.setItem("incremental_sync_token", this.syncToken);
        }
    }

    private async loadState(): Promise<void> {
        try {
            this.syncToken = await this.store.getItem("incremental_sync_token");
        } catch (error) {
            logger.warn("Failed to load incremental sync state:", error);
        }
    }

    private async saveRoomState(roomId: string): Promise<void> {
        const roomState = this.roomStates.get(roomId);
        if (!roomState) {
            return;
        }

        const stateData = {
            prevBatch: roomState.prevBatch,
            events: roomState.events,
            state: Array.from(roomState.state.entries()),
        };

        await this.store.setItem(`room_state_${roomId}`, stateData);
    }
}
